begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(47);
insert into public.clinics(id,name) values('f1000000-0000-4000-8000-000000000001','Synthetic Language A'),('f1000000-0000-4000-8000-000000000002','Synthetic Language B');
insert into auth.users(id) values('f2000000-0000-4000-8000-000000000001'),('f2000000-0000-4000-8000-000000000002');
insert into public.clinic_memberships(clinic_id,user_id,role,active) values('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','reception',true),('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000002','manager',true);
insert into public.inquiries(id,clinic_id,owner_user_id,display_name,source) values('f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Synthetic Language','phone');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
select set_config('request.method','POST',true);
create function pg_temp.language(p jsonb,k uuid default gen_random_uuid()) returns jsonb language sql as $$select public.set_inquiry_communication_language('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001',k,p,'f5000000-0000-4000-8000-000000000001')$$;
create function pg_temp.state() returns jsonb language sql as $$select public.get_inquiry_communication_language('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001')$$;
select ok(not has_function_privilege('anon','public.get_inquiry_communication_language(uuid,uuid)','EXECUTE') and not has_function_privilege('anon','public.set_inquiry_communication_language(uuid,uuid,uuid,jsonb,uuid)','EXECUTE'),'anonymous RPCs denied');
select is((select enabled from private.intake_command_settings),false,'commands default off');
set local role authenticated;
select is(pg_temp.state()->>'revision','0','initial read independent of write switch');
select is(pg_temp.state()->'language','null'::jsonb,'initial language unrecorded');
select is(pg_temp.state()->'updated_at','null'::jsonb,'initial update time absent');
select throws_ok($$select pg_temp.language('{"expected_revision":0,"language":"fr"}')$$,'PT503',null,'direct RPC write gate enforced');
select throws_ok($$select * from private.inquiry_communication_languages$$,'42501',null,'state table private');
select throws_ok($$select * from private.inquiry_communication_language_receipts$$,'42501',null,'receipt table private');
reset role;
select throws_ok($$select public.get_inquiry_communication_language('f1000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000001')$$,'42501',null,'privileged foreign clinic lacks active membership');
select throws_ok($$select public.get_inquiry_communication_language('f1000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000099')$$,'PT404',null,'missing inquiry not found');
select set_config('request.method','GET',true);
select throws_ok($$select pg_temp.state()$$,'22023',null,'read RPC requires POST');
select throws_ok($$select pg_temp.language('{"expected_revision":0,"language":"fr"}')$$,'22023',null,'write RPC requires POST');
select set_config('request.method','POST',true);
update private.intake_command_settings set enabled=true;
select is((pg_temp.language('{"expected_revision":0,"language":null}')->'receipt'->>'changed')::boolean,false,'initial null no-op is deliberate');
select is((select count(*)::int from private.inquiry_communication_languages where clinic_id='f1000000-0000-4000-8000-000000000001'),0,'no-op does not materialize state');
select is((select count(*)::int from private.outbox_events where clinic_id='f1000000-0000-4000-8000-000000000001'),0,'no-op has no event');
select is(pg_temp.language('{"expected_revision":0,"language":"fr"}','f4000000-0000-4000-8000-000000000001')->'receipt'->>'revision','1','real change advances exactly one');
select is((pg_temp.language('{"expected_revision":0,"language":"fr"}','f4000000-0000-4000-8000-000000000001')->>'replayed')::boolean,true,'exact key replay before CAS');
select throws_ok($$select pg_temp.language('{"expected_revision":0,"language":"en"}','f4000000-0000-4000-8000-000000000001')$$,'PT409',null,'different payload key conflict');
select is(pg_temp.language('{"expected_revision":1,"language":"en"}')->'receipt'->>'revision','2','language independent of contact detail');
select is(pg_temp.language('{"expected_revision":2,"language":"fr"}')->'receipt'->>'revision','3','A B A retains increasing revision');
select throws_ok($$select pg_temp.language('{"expected_revision":1,"language":"fr"}')$$,'PT409',null,'stale A B A cannot no-op');
select is((select count(*)::int from private.outbox_events e cross join lateral jsonb_object_keys(e.payload) where e.clinic_id='f1000000-0000-4000-8000-000000000001'),15,'three events each have exactly five payload fields');
select throws_ok($$update private.inquiry_communication_language_receipts set receipt='{}' where clinic_id='f1000000-0000-4000-8000-000000000001'$$,'55000',null,'receipts immutable');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000002',true);
select throws_ok($$select pg_temp.state()$$,'PT404',null,'other manager cannot read');
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":null}')$$,'PT404',null,'other manager cannot change');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
update public.inquiries set owner_user_id='f2000000-0000-4000-8000-000000000002' where id='f3000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.language('{"expected_revision":0,"language":"fr"}','f4000000-0000-4000-8000-000000000001')$$,'PT404',null,'former owner cannot replay');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000002',true);
select is(pg_temp.state()->>'owner_user_id','f2000000-0000-4000-8000-000000000002','new owner projection has current identity only');
select is(pg_temp.state()->>'language','fr','language follows inquiry');
update public.inquiries set owner_user_id='f2000000-0000-4000-8000-000000000001' where id='f3000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
update private.intake_command_settings set enabled=false;
select throws_ok($$select pg_temp.language('{"expected_revision":0,"language":"fr"}','f4000000-0000-4000-8000-000000000001')$$,'PT503',null,'disabled replay denied');
select is(pg_temp.state()->>'language','fr','read remains available disabled');
update private.intake_command_settings set enabled=true;
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":"fr","consent":true}')$$,'22023',null,'consent field forbidden');
select throws_ok($$select pg_temp.language('{"expected_revision":3.5,"language":"fr"}')$$,'22023',null,'noninteger revision rejected');
create function pg_temp.fail_language_sink() returns trigger language plpgsql as $$begin raise exception 'synthetic sink failure';end$$;
create trigger fail_language_sink before insert on private.outbox_events for each row execute function pg_temp.fail_language_sink();
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":null}')$$,'P0001','synthetic sink failure','outbox failure aborts command');
select is(pg_temp.state()->>'revision','3','state rolls back with event');
select is((select count(*)::int from private.inquiry_communication_language_receipts where clinic_id='f1000000-0000-4000-8000-000000000001'),4,'failed receipt rolled back');
drop trigger fail_language_sink on private.outbox_events;
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":"FR"}')$$,'22023',null,'case aliases rejected');
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":" fr"}')$$,'22023',null,'whitespace not normalized');
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":"fr-MA"}')$$,'22023',null,'locale aliases rejected');
select throws_ok($$select pg_temp.language('{"expected_revision":3,"language":"other","language_label":"private"}')$$,'22023',null,'free text not stored');
select is(pg_temp.language('{"expected_revision":3,"language":"ar"}')->'receipt'->>'revision','4','Arabic explicit code accepted');
select is(pg_temp.language('{"expected_revision":4,"language":"other"}')->'receipt'->>'revision','5','other explicit code accepted');
select is(pg_temp.language('{"expected_revision":5,"language":"no_preference"}')->'receipt'->>'revision','6','explicit absence differs from unrecorded');
select is(pg_temp.language('{"expected_revision":6,"language":null}')->'receipt'->>'revision','7','clearing advances revision');
select is(pg_temp.language('{"expected_revision":7,"language":"fr"}')->'receipt'->>'revision','8','French restored before ceiling check');
update private.inquiry_communication_languages set revision=2147483647 where clinic_id='f1000000-0000-4000-8000-000000000001';
select is(pg_temp.language('{"expected_revision":2147483647,"language":"fr"}')->'receipt'->>'revision','2147483647','ceiling no-op allowed');
select throws_ok($$select pg_temp.language('{"expected_revision":2147483647,"language":null}')$$,'PT409',null,'ceiling change rejected without overflow');
update public.clinic_memberships set role='assistant' where user_id='f2000000-0000-4000-8000-000000000001';
select throws_ok($$select pg_temp.state()$$,'42501',null,'privileged assistant denied');
select * from finish();
rollback;
